import { CFB } from 'xlsx';

// SheetJS CE writes margins and merged cells, but omits fit-to-page setup.
// Adjust only the four statement sheets in the XLSX generated by this module.
export function fitStatementPages(bytes: ArrayBuffer): ArrayBuffer {
  const zip = CFB.read(new Uint8Array(bytes), { type:'array' });
  const decode = new TextDecoder(), encode = new TextEncoder();
  for (let n = 1; n <= 4; n++) {
    const path = 'Root Entry/xl/worksheets/sheet' + n + '.xml';
    const entry = zip.FileIndex[zip.FullPaths.indexOf(path)];
    let xml = decode.decode(entry.content);
    const fit = '<pageSetUpPr fitToPage="1"/>';
    if (xml.includes('</sheetPr>')) xml = xml.replace('</sheetPr>',fit + '</sheetPr>');
    else xml = xml.replace('<dimension ', '<sheetPr>' + fit + '</sheetPr><dimension ');
    const setup = '<pageSetup paperSize="9" orientation="landscape" fitToWidth="1" fitToHeight="0"/>';
    xml = xml.replace(/<pageMargins\b[^>]*\/>/, margins => margins + setup);
    entry.content = encode.encode(xml);
    entry.size = entry.content.length;
  }
  return Uint8Array.from(CFB.write(zip,{type:'array',fileType:'zip',compression:true})).buffer;
}
